targets.rawSql:
WITH p AS (SELECT statement_timestamp() AS t) SELECT principal_type,principal_id,count(*)::integer AS violation_count,count(DISTINCT resource_ref)::integer AS distinct_resource_count FROM audit_event CROSS JOIN p WHERE occurred_at>p.t-interval '5 minutes' AND occurred_at<=p.t AND principal_type IN ('CUSTOMER','PARTNER') AND principal_id IS NOT NULL
AND result='DENIED' AND reason_code='OBJECT_ACCESS_DENIED'
AND action IN ('ACCOUNT_READ','TRANSACTION_READ','GRANT_CREATE','GRANT_REVOKE') AND resource_ref IS NOT NULL GROUP BY principal_type,principal_id ORDER BY violation_count DESC,principal_type,principal_id LIMIT 100;
